package com.lootfinder;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.ArrayList;
import java.util.function.Consumer;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuShouldLeftClick;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.loottracker.LootTrackerPlugin;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

final class LootBankButton
{
	private static final String OPEN_MENU = "Open loot sources";
	private static final String ADD_FAVORITE = "Add to favorites";
	@Inject private Client client;
	private Widget parent;
	private Widget button;
	private BufferedImage image;
	private SpritePixels sprite;
	private int spriteId;
	private List<LootSource> recents = java.util.Collections.emptyList();
	private List<LootSource> favorites = java.util.Collections.emptyList();
	private Consumer<LootSource> selection;
	private BooleanSupplier canAddFavorite;
	private LootMenuLocation location;
	private Runnable clearFilter;
	private Runnable addCurrentFavorite;

	void loadImage()
	{
		image = ImageUtil.loadImageResource(LootTrackerPlugin.class, "panel_icon.png");
	}

	void show(LootMenuLocation location, List<LootSource> sources, List<LootSource> favoriteSources, Consumer<LootSource> select,
		Runnable clear, BooleanSupplier canAddFavorite, Runnable addFavorite)
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden()) return;
		if (parent != bank) detach();
		parent = bank;
		this.location = location;
		recents = List.copyOf(sources);
		favorites = List.copyOf(favoriteSources);
		selection = select;
		this.canAddFavorite = canAddFavorite;
		clearFilter = clear;
		addCurrentFavorite = addFavorite;
		if (location != LootMenuLocation.SEPARATE_ICON)
		{
			if (button != null)
			{
				button.clearActions();
				button.setOnOpListener((Object[]) null);
				button.setHidden(true);
			}
			return;
		}
		if (sprite == null)
		{
			sprite = ImageUtil.getImageSpritePixels(image, client);
			// Allocate a free custom sprite ID rather than replacing another plugin's sprite.
			spriteId = -10000;
			while (client.getSpriteOverrides().containsKey(spriteId)) spriteId--;
			client.getSpriteOverrides().put(spriteId, sprite);
		}
		if (button == null)
		{
			button = bank.createChild(-1, WidgetType.GRAPHIC);
			button.setOriginalWidth(20);
			button.setOriginalHeight(20);
			button.setOriginalX(380);
			button.setOriginalY(7);
			button.setSpriteId(spriteId);
			button.setHasListener(true);
		}
		button.setHidden(false);
		button.setName("Loot Finder");
		button.clearActions();
		button.setAction(0, OPEN_MENU);
		button.setAction(1, "Recents");
		button.setAction(2, "Favorites");
		button.setAction(3, "Clear loot filter");
		button.setAction(4, ADD_FAVORITE);
		button.setOnOpListener((JavaScriptCallback) event ->
		{
			if (event.getOp() == 4) clear.run();
			else if (event.getOp() == 5 && canAddFavorite.getAsBoolean()) addFavorite.run();
		});
		button.revalidate();
	}

	void onMenuShouldLeftClick(MenuShouldLeftClick event)
	{
		if (location != LootMenuLocation.SEPARATE_ICON || button == null || button.isHidden()) return;
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length > 0 && entries[entries.length - 1].getWidget() == button)
		{
			event.setForceRightClick(true);
		}
	}

	void onMenuOpened(MenuOpened event)
	{
		if (!isBankOpen()) return;
		if (location == LootMenuLocation.BANK_SETTINGS || location == LootMenuLocation.BANK_HELP)
		{
			Widget menuButton = client.getWidget(location == LootMenuLocation.BANK_HELP
				? InterfaceID.Bankmain.BANK_TUT : InterfaceID.Bankmain.MENU_BUTTON);
			if (menuButton == null || menuButton.isHidden()) return;
			for (MenuEntry entry : event.getMenuEntries())
			{
				if (entry.getWidget() == menuButton)
				{
					addBankButtonMenus();
					break;
				}
			}
			return;
		}
		if (button == null || button.isHidden()) return;
		List<MenuEntry> visibleEntries = new ArrayList<>();
		boolean removedOpener = false;
		for (MenuEntry entry : event.getMenuEntries())
		{
			// Keep the opener for hover text, but omit it once the menu is open.
			if (entry.getWidget() == button && (OPEN_MENU.equals(entry.getOption())
				|| (ADD_FAVORITE.equals(entry.getOption())
					&& (canAddFavorite == null || !canAddFavorite.getAsBoolean()))))
			{
				removedOpener = true;
				continue;
			}
			visibleEntries.add(entry);
			if (entry.getWidget() != button) continue;
			if ("Favorites".equals(entry.getOption())) populate(entry, favorites, "No matching favorites — configure source names");
			else if ("Recents".equals(entry.getOption())) populate(entry, recents, "No recorded loot");
		}
		if (removedOpener)
		{
			client.getMenu().setMenuEntries(visibleEntries.toArray(new MenuEntry[0]));
		}
	}

	private boolean isBankOpen()
	{
		return parent != null && !parent.isHidden()
			&& client.getWidget(InterfaceID.Bankmain.UNIVERSE) == parent;
	}

	private void addBankButtonMenus()
	{
		Menu menu = client.getMenu();
		// Only add client-side menu entries; leave the bank widget and its actions intact.
		// The last entry is displayed first, so add our actions in reverse display order.
		if (canAddFavorite != null && canAddFavorite.getAsBoolean())
		{
			menu.createMenuEntry(-1).setOption(ADD_FAVORITE).setTarget("Loot Finder")
				.setType(MenuAction.RUNELITE).onClick(entry ->
				{
					if (isBankOpen() && canAddFavorite != null && canAddFavorite.getAsBoolean()
						&& addCurrentFavorite != null) addCurrentFavorite.run();
				});
		}
		menu.createMenuEntry(-1).setOption("Clear loot filter").setTarget("Loot Finder")
			.setType(MenuAction.RUNELITE).onClick(entry ->
			{
				if (isBankOpen() && clearFilter != null) clearFilter.run();
			});
		populate(menu.createMenuEntry(-1).setOption("Favorites"), favorites, "No matching favorites — configure source names");
		populate(menu.createMenuEntry(-1).setOption("Recents"), recents, "No recorded loot");
	}

	private void populate(MenuEntry entry, List<LootSource> sources, String emptyMessage)
	{
		String section = entry.getOption();
		entry.setOption("Loot Finder:");
		entry.setTarget("<col=ff981f>" + section + "</col>");
		entry.setType(MenuAction.RUNELITE);
		Menu submenu = entry.createSubMenu();
		if (sources.isEmpty())
		{
			submenu.createMenuEntry(0).setOption(emptyMessage).setType(MenuAction.RUNELITE);
			return;
		}
		for (LootSource source : sources)
		{
			boolean duplicateName = sources.stream().filter(other -> other.getName().equals(source.getName())).count() > 1;
			String label = source.getName() + (duplicateName ? " (" + source.getType() + ")" : "");
			submenu.createMenuEntry(0)
				.setOption("Show loot")
				.setTarget("<col=ff981f>" + Text.escapeJagex(label) + "</col>")
				.setType(MenuAction.RUNELITE)
				.onClick(clicked ->
				{
					if (isBankOpen() && selection != null) selection.accept(source);
				});

		}
	}

	void detach()
	{
		if (button != null)
		{
			button.clearActions();
			button.setOnOpListener((Object[]) null);
			button.setHidden(true);
		}
		button = null;
		parent = null;
		recents = java.util.Collections.emptyList();
		favorites = java.util.Collections.emptyList();
		selection = null;
		canAddFavorite = null;
		clearFilter = null;
		addCurrentFavorite = null;
		location = null;
	}

	void shutDown()
	{
		detach();
		if (sprite != null)
		{
			client.getSpriteOverrides().remove(spriteId, sprite);
			sprite = null;
		}
		image = null;
	}
}

package com.lootfinder;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTag;

final class LootBankTag implements BankTag
{
	@Inject private ItemManager itemManager;
	private Set<Integer> items = Collections.emptySet();

	void select(LootSource source)
	{
		Set<Integer> next = new HashSet<>();
		for (int id : source.getItemIds()) next.add(itemManager.canonicalize(id));
		items = next;
	}

	void clear()
	{
		items = Collections.emptySet();
	}

	@Override
	public boolean contains(int itemId)
	{
		return itemId > 0 && items.contains(itemManager.canonicalize(itemId));
	}
}

package com.lootfinder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(LootFinderConfig.GROUP)
public interface LootFinderConfig extends Config
{
    String GROUP = "loot-finder";

    @ConfigItem(keyName = "menuLocation", name = "Menu location", description = "Use a separate icon or use existing bank buttons with a right click")
    default LootMenuLocation menuLocation()
    {
        return LootMenuLocation.SEPARATE_ICON;
    }

    // Retain the stored key so existing favorites remain saved.
    @ConfigItem(keyName = "favoriteNpcs", name = "Favorite loot sources", description = "Examples: Corrupted Hunllef, Seed pack")
    default String favoriteSources()
    {
        return "";
    }


    @Range(min = 1, max = 20)
    @ConfigItem(keyName = "recentSources", name = "Recent loot sources", description = "Number of recent Loot Tracker sources in the bank menu")
    default int recentSources()
    {
        return 5;
    }
}

package com.lootfinder;

import java.util.function.BiFunction;

final class LootFinderConfigMigration
{
	@FunctionalInterface
	interface Writer
	{
		void set(String group, String key, String value);
	}

	private LootFinderConfigMigration() {}

	static void migrate(BiFunction<String, String, String> read, Writer write)
	{
		String group = LootFinderConfig.GROUP;
		if ("true".equals(read.apply(group, "legacyConfigMigrated"))) return;
		copy(read, write, "favoriteNpcs", "");
		copy(read, write, "recentSources", "5");
		write.set(group, "legacyConfigMigrated", "true");
	}

	private static void copy(BiFunction<String, String, String> read, Writer write, String key, String defaultValue)
	{
		String oldValue = read.apply("LootFinder", key);
		String current = read.apply(LootFinderConfig.GROUP, key);
		// Defaults may already have been populated when switching RuneLite profiles.
		if (oldValue != null && (current == null || current.equals(defaultValue)))
		{
			write.set(LootFinderConfig.GROUP, key, oldValue);
		}
	}
}

package com.lootfinder;

import com.google.inject.Provides;
import javax.inject.Inject;
import java.util.UUID;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuShouldLeftClick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsConfig;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;

@PluginDescriptor(name = "Loot Finder", description = "Filter loot in your bank from the Loot Tracker plugin", tags = {"bank", "loot", "tags"})
@PluginDependency(BankTagsPlugin.class)
public class LootFinderPlugin extends Plugin
{
	// One private, session-only name avoids merging with a user's saved tag.
	private final String tagName = "loot-finder:" + UUID.randomUUID();
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private LootFinderConfig config;
	@Inject private ConfigManager configManager;
	@Inject private LootTrackerRepository repository;
	@Inject private LootBankTag tag;
	@Inject private LootBankButton button;
	@Inject private TagManager tagManager;
	@Inject private BankTagsService bankTags;
	private boolean running;
	private boolean registered;
	private String selectedSourceName;

	@Provides
	LootFinderConfig provideConfig(ConfigManager manager)
	{
		LootFinderConfigMigration.migrate(manager::getConfiguration, manager::setConfiguration);
		return manager.getConfig(LootFinderConfig.class);
	}

	@Override
	protected void startUp()
	{
		button.loadImage();
		running = true;
		clientThread.invokeLater(() ->
		{
			if (!running) return;
			removeStaleLootTab();
			refresh();
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		clientThread.invokeLater(() ->
		{
			clear();
			unregister();
			button.shutDown();
			repository.clearLive();
		});
	}

	private void refresh()
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN) return;
		List<LootSource> all = repository.recent(Integer.MAX_VALUE);
		List<LootSource> recent = all.subList(0, Math.min(all.size(), Math.max(1, Math.min(20, config.recentSources()))));
		button.show(config.menuLocation(), recent, LootTrackerRepository.favorites(all, config.favoriteSources()), source ->
		{
			if (!running) return;
			tag.select(source);
			selectedSourceName = source.getName();
			if (!registered)
			{
			tagManager.registerTag(tagName, tag);
				registered = true;
			}
			openSelectedLootFilter();
		}, this::clear, this::canAddCurrentFavorite, this::addCurrentFavorite);
	}

	private boolean canAddCurrentFavorite()
	{
		if (!running || selectedSourceName == null || !tagName.equals(bankTags.getActiveTag())) return false;
		String favorites = config.favoriteSources();
		if (favorites != null)
		{
			for (String name : favorites.split(","))
			{
				if (name.trim().equalsIgnoreCase(selectedSourceName.trim())) return false;
			}
		}
		return true;
	}

	private void addCurrentFavorite()
	{
		if (!canAddCurrentFavorite()) return;
		String favorites = config.favoriteSources();
		String updated = favorites == null || favorites.trim().isEmpty()
			? selectedSourceName : favorites + ", " + selectedSourceName;
		configManager.setConfiguration(LootFinderConfig.GROUP, "favoriteNpcs", updated);
		// ConfigChanged refreshes the menu using the saved favorites.
	}

	private void openSelectedLootFilter()
	{
		if (!running || selectedSourceName == null || !registered) return;
		// Allow normal bank dragging while keeping the filter in the bank's actual order.
		bankTags.openBankTag(tagName, BankTagsService.OPTION_NO_LAYOUT
			| BankTagsService.OPTION_HIDE_TAG_NAME | BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		// Keep the selection in memory without saving a session-only tag in Bank Tags.
		forgetLootTab();
	}

	private static boolean isLootTab(String name)
	{
		return name != null && name.matches("loot-finder:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");
	}

	private void forgetLootTab()
	{
		// Dependency plugins expose services, not their private config bindings.
		BankTagsConfig bankTagsConfig = configManager.getConfig(BankTagsConfig.class);
		if (isLootTab(bankTagsConfig.tab())) bankTagsConfig.tab("");
	}

	private void removeStaleLootTab()
	{
		// Recover UUID tags saved by earlier versions, including across client restarts.
		if (selectedSourceName == null && isLootTab(bankTags.getActiveTag()))
		{
			bankTags.closeBankTag();
		}
		forgetLootTab();
	}

	private void clear()
	{
		selectedSourceName = null;
		if (tagName.equals(bankTags.getActiveTag())) bankTags.closeBankTag();
		tag.clear();
	}

	private void unregister()
	{
		forgetLootTab();
		if (registered) tagManager.unregisterTag(tagName);
		registered = false;
		selectedSourceName = null;
		tag.clear();
	}

	// Follow Bank Tags' own pre-init restoration, after it initializes its tab UI.
	@Subscribe(priority = -1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_INIT
			&& running && registered && selectedSourceName != null)
		{
			// The server restores the vanilla tab on bank open; use all items for loot filtering.
			client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
			openSelectedLootFilter();
		}
	}

	// Set the label before BankPlugin's default-priority handler appends bank value.
	@Subscribe(priority = 1)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_INIT)
		{
			Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
			// ScriptPostFired still runs inside the interpreter. Defer stale-tag cleanup,
			// which can run scripts, but do not rebuild the already restored filter.
			clientThread.invokeLater(() ->
			{
				if (!running || client.getGameState() != GameState.LOGGED_IN
					|| bank == null || bank.isHidden()
					|| client.getWidget(InterfaceID.Bankmain.UNIVERSE) != bank) return;
				removeStaleLootTab();
				refresh();
			});
		}
		else if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING
			&& running && selectedSourceName != null && tagName.equals(bankTags.getActiveTag()))
		{
			Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
			if (title != null)
			{
				title.setText("Loot: " + Text.escapeJagex(selectedSourceName));
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			// Bank Tags clears its active filter on close; retain ours for the next open.
			button.detach();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			if (!running) return;
			clear();
			unregister();
			button.detach();
			refresh();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			unregister();
			button.detach();
		}
		else if (event.getGameState() == GameState.HOPPING)
		{
			button.detach();
		}
	}

	@Subscribe
	public void onMenuShouldLeftClick(MenuShouldLeftClick event)
	{
		if (running) button.onMenuShouldLeftClick(event);
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!running) return;
		button.onMenuOpened(event);
		if (tagName.equals(bankTags.getActiveTag()))
		{
			// Bank Tags couples dragging with tag-edit actions. Loot membership is derived
			// from recorded drops, so removing a saved tag would have no effect here.
			for (MenuEntry entry : client.getMenu().getMenuEntries())
			{
				if (entry.getType() == MenuAction.RUNELITE
					&& entry.getParam1() == InterfaceID.Bankmain.ITEMS
					&& "Remove-tag".equals(entry.getOption()))
				{
					client.getMenu().removeMenuEntry(entry);
				}
			}
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		LootFinderConfigMigration.migrate(configManager::getConfiguration, configManager::setConfiguration);
		clientThread.invokeLater(() ->
		{
			repository.clearLive();
			refresh();
		});
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invoke(() ->
		{
			if (!running || !java.util.Objects.equals(profile, configManager.getRSProfileKey())) return;
			repository.record(profile, event);
			// The next bank open reads these updates even when no bank UI exists yet.
			Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
			if (bank != null && !bank.isHidden()) refresh();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("loottracker".equals(event.getGroup()) && event.getKey().startsWith("drops_"))
		{
			clientThread.invokeLater(() ->
			{
				if (!running || !java.util.Objects.equals(event.getProfile(), configManager.getRSProfileKey())) return;
				if (event.getNewValue() == null) repository.removeLive(event.getProfile(), event.getKey());
				Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
				if (bank != null && !bank.isHidden()) refresh();
			});
			return;
		}
		if (LootFinderConfig.GROUP.equals(event.getGroup())
			|| ("loottracker".equals(event.getGroup()) && "ignoredEvents".equals(event.getKey())))
		{
			clientThread.invokeLater(this::refresh);
		}
	}
}

package com.lootfinder;

public enum LootMenuLocation
{
	SEPARATE_ICON("Separate icon"),
	BANK_SETTINGS("Bank wrench"),
	BANK_HELP("Bank help");

	private final String label;

	LootMenuLocation(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.lootfinder;

import java.time.Instant;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import lombok.Getter;

@Getter
final class LootSource
{
	private final String name;
	private final String type;
	private final Instant last;
	private final Set<Integer> itemIds;

	LootSource(String type, String name, Instant last, Set<Integer> itemIds)
	{
		this.type = type;
		this.name = name;
		this.last = last;
		this.itemIds = Collections.unmodifiableSet(new HashSet<>(itemIds));
	}
}

